    { const char * tb_v952 = "static int tb_thread_create(pthread_t *th, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v952; }
    { const char * tb_v953 = "    tb_tramp *t = malloc(sizeof(tb_tramp));\n"; *(const char * *)tb_grow(v_lines) = tb_v953; }
    { const char * tb_v954 = "    if (!t) return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v954; }
    { const char * tb_v955 = "    t->run = run; t->arg = arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v955; }
    { const char * tb_v956 = "    pthread_attr_t at;\n"; *(const char * *)tb_grow(v_lines) = tb_v956; }
    { const char * tb_v957 = "    pthread_attr_init(&at);\n"; *(const char * *)tb_grow(v_lines) = tb_v957; }
    { const char * tb_v958 = "    pthread_attr_setstacksize(&at, (size_t)TB_THREAD_STACK);\n"; *(const char * *)tb_grow(v_lines) = tb_v958; }
    { const char * tb_v959 = "    __atomic_add_fetch(&tb_gthreads, 1, __ATOMIC_ACQ_REL);\n"; *(const char * *)tb_grow(v_lines) = tb_v959; }
    { const char * tb_v960 = "    int r = pthread_create(th, &at, tb_tramp_run, t);\n"; *(const char * *)tb_grow(v_lines) = tb_v960; }
    { const char * tb_v961 = "    pthread_attr_destroy(&at);\n"; *(const char * *)tb_grow(v_lines) = tb_v961; }
    { const char * tb_v962 = "    if (r != 0) { free(t); __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE); }\n"; *(const char * *)tb_grow(v_lines) = tb_v962; }
    { const char * tb_v963 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v963; }
    { const char * tb_v964 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v964; }
    { const char * tb_v965 = "static void tb_guard_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v965; }
    { const char * tb_v966 = "    static char alt[65536];\n"; *(const char * *)tb_grow(v_lines) = tb_v966; }
    { const char * tb_v967 = "    stack_t ss;\n"; *(const char * *)tb_grow(v_lines) = tb_v967; }
    { const char * tb_v968 = "    ss.ss_sp = alt; ss.ss_size = sizeof alt; ss.ss_flags = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v968; }
    { const char * tb_v969 = "    sigaltstack(&ss, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v969; }
    { const char * tb_v970 = "    struct sigaction sa;\n"; *(const char * *)tb_grow(v_lines) = tb_v970; }
    { const char * tb_v971 = "    memset(&sa, 0, sizeof sa);\n"; *(const char * *)tb_grow(v_lines) = tb_v971; }
    { const char * tb_v972 = "    sa.sa_sigaction = tb_on_segv;\n"; *(const char * *)tb_grow(v_lines) = tb_v972; }
    { const char * tb_v973 = "    sa.sa_flags = SA_SIGINFO | SA_ONSTACK;\n"; *(const char * *)tb_grow(v_lines) = tb_v973; }
    { const char * tb_v974 = "    sigaction(SIGSEGV, &sa, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v974; }
    { const char * tb_v975 = "    sigaction(SIGBUS, &sa, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v975; }
    { const char * tb_v976 = "    char here;\n"; *(const char * *)tb_grow(v_lines) = tb_v976; }
    { const char * tb_v977 = "    tb_main_sp = &here;\n"; *(const char * *)tb_grow(v_lines) = tb_v977; }
    { const char * tb_v978 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v978; }
    { const char * tb_v979 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v979; }
    { const char * tb_v980 = "// ---------- temp: временная память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v980; }
    { const char * tb_v981 = "// Внутри блока temp память берётся из больших кусков подряд (быстро, без malloc),\n"; *(const char * *)tb_grow(v_lines) = tb_v981; }
    { const char * tb_v982 = "// а в конце блока все куски отдаются разом. У каждого ядра свои куски.\n"; *(const char * *)tb_grow(v_lines) = tb_v982; }
    { const char * tb_v983 = "typedef struct { char *mem; long long size, used; } tb_chunk;\n"; *(const char * *)tb_grow(v_lines) = tb_v983; }
    { const char * tb_v984 = "typedef struct { int n; long long used; } tb_mark;\n"; *(const char * *)tb_grow(v_lines) = tb_v984; }
    { const char * tb_v985 = "static _Thread_local tb_chunk *tb_chunks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v985; }
    { const char * tb_v986 = "static _Thread_local int tb_nchunks = 0, tb_capchunks = 0, tb_temp_depth = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v986; }
    { const char * tb_v987 = "static int tb_in_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v987; }
    { const char * tb_v988 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v988; }
    { const char * tb_v989 = "        if ((const char *)p >= tb_chunks[i].mem && (const char *)p < tb_chunks[i].mem + tb_chunks[i].size) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v989; }
    { const char * tb_v990 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v990; }
    { const char * tb_v991 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v991; }
    { const char * tb_v992 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v992; }
    { const char * tb_v993 = "static void *tb_temp_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v993; }
    { const char * tb_v994 = "    n = n > 0 ? (n + 15) & ~15LL : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v994; }
    { const char * tb_v995 = "    tb_chunk *c = tb_nchunks > 0 ? &tb_chunks[tb_nchunks - 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v995; }
    { const char * tb_v996 = "    if (c == 0 || c->used + n > c->size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v996; }
    { const char * tb_v997 = "        long long size = c != 0 ? c->size * 2 : (1LL << 20);\n"; *(const char * *)tb_grow(v_lines) = tb_v997; }
    { const char * tb_v998 = "        if (size < n) size = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v998; }
    { const char * tb_v999 = "        if (tb_nchunks == tb_capchunks) {\n"; *(const char * *)tb_grow(v_lines) = tb_v999; }
    { const char * tb_v1000 = "            tb_capchunks = tb_capchunks * 2 + 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v1000; }
    { const char * tb_v1001 = "            tb_chunks = realloc(tb_chunks, sizeof(tb_chunk) * tb_capchunks);\n"; *(const char * *)tb_grow(v_lines) = tb_v1001; }
    { const char * tb_v1002 = "            if (tb_chunks == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1002; }
    { const char * tb_v1003 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v1003; }
    { const char * tb_v1004 = "        char *mem = malloc(size);\n"; *(const char * *)tb_grow(v_lines) = tb_v1004; }
    { const char * tb_v1005 = "        if (mem == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1005; }
    { const char * tb_v1006 = "        tb_chunks[tb_nchunks] = (tb_chunk){mem, size, 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v1006; }
    { const char * tb_v1007 = "        c = &tb_chunks[tb_nchunks];\n"; *(const char * *)tb_grow(v_lines) = tb_v1007; }
    { const char * tb_v1008 = "        tb_nchunks += 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1008; }
    { const char * tb_v1009 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1009; }
    { const char * tb_v1010 = "    void *p = c->mem + c->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v1010; }
    { const char * tb_v1011 = "    c->used += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1011; }
    { const char * tb_v1012 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1012; }
    { const char * tb_v1013 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1013; }
    { const char * tb_v1014 = "// метки открытых temp (и арен шага / функции): самая последняя — текущая область\n"; *(const char * *)tb_grow(v_lines) = tb_v1014; }
    { const char * tb_v1015 = "static _Thread_local tb_mark *tb_marks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1015; }
    { const char * tb_v1016 = "static _Thread_local int tb_capmarks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1016; }
    { const char * tb_v1017 = "static inline tb_mark tb_temp_begin(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1017; }
    { const char * tb_v1018 = "    tb_mark m = {tb_nchunks, tb_nchunks > 0 ? tb_chunks[tb_nchunks - 1].used : 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v1018; }
    { const char * tb_v1019 = "    if (tb_temp_depth == tb_capmarks) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1019; }
    { const char * tb_v1020 = "        tb_capmarks = tb_capmarks * 2 + 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v1020; }
    { const char * tb_v1021 = "        tb_marks = realloc(tb_marks, sizeof(tb_mark) * tb_capmarks);\n"; *(const char * *)tb_grow(v_lines) = tb_v1021; }
    { const char * tb_v1022 = "        if (tb_marks == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1022; }
    { const char * tb_v1023 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1023; }
    { const char * tb_v1024 = "    tb_marks[tb_temp_depth] = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v1024; }
    { const char * tb_v1025 = "    tb_temp_depth += 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1025; }
    { const char * tb_v1026 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v1026; }
    { const char * tb_v1027 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1027; }
    { const char * tb_v1028 = "// p во временной памяти текущей (самой внутренней) области, а не во внешней\n"; *(const char * *)tb_grow(v_lines) = tb_v1028; }
    { const char * tb_v1029 = "static int tb_in_cur_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1029; }
    { const char * tb_v1030 = "    if (tb_temp_depth == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1030; }
    { const char * tb_v1031 = "    tb_mark t = tb_marks[tb_temp_depth - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v1031; }
    { const char * tb_v1032 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1032; }
    { const char * tb_v1033 = "        const char *m = tb_chunks[i].mem;\n"; *(const char * *)tb_grow(v_lines) = tb_v1033; }
    { const char * tb_v1034 = "        if ((const char *)p >= m && (const char *)p < m + tb_chunks[i].size)\n"; *(const char * *)tb_grow(v_lines) = tb_v1034; }
    { const char * tb_v1035 = "            return i > t.n - 1 || (i == t.n - 1 && (const char *)p - m >= t.used);\n"; *(const char * *)tb_grow(v_lines) = tb_v1035; }
    { const char * tb_v1036 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1036; }
    { const char * tb_v1037 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1037; }
    { const char * tb_v1038 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1038; }
    { const char * tb_v1039 = "// длина последних текстов: s[i] в цикле не пересчитывает strlen каждый раз\n"; *(const char * *)tb_grow(v_lines) = tb_v1039; }
    { const char * tb_v1040 = "static _Thread_local const char *tb_lc_p[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v1040; }
    { const char * tb_v1041 = "static _Thread_local long long tb_lc_n[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v1041; }
    { const char * tb_v1042 = "static _Thread_local int tb_lc_next;\n"; *(const char * *)tb_grow(v_lines) = tb_v1042; }
    { const char * tb_v1043 = "static inline void tb_lc_clear(void) { tb_lc_p[0] = 0; tb_lc_p[1] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1043; }
    { const char * tb_v1044 = "static inline void tb_temp_end(tb_mark m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1044; }
    { const char * tb_v1045 = "    // первый кусок оставляем пустым: следующий temp возьмёт его без malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1045; }
    { const char * tb_v1046 = "    while (tb_nchunks > m.n && tb_nchunks > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1046; }
    { const char * tb_v1047 = "        tb_nchunks -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1047; }
    { const char * tb_v1048 = "        free(tb_chunks[tb_nchunks].mem);\n"; *(const char * *)tb_grow(v_lines) = tb_v1048; }
    { const char * tb_v1049 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1049; }
    { const char * tb_v1050 = "    if (tb_nchunks > m.n) tb_chunks[0].used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1050; }
    { const char * tb_v1051 = "    else if (tb_nchunks > 0) tb_chunks[tb_nchunks - 1].used = m.used;\n"; *(const char * *)tb_grow(v_lines) = tb_v1051; }
    { const char * tb_v1052 = "    tb_temp_depth -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1052; }
    { const char * tb_v1053 = "    tb_lc_clear();\n"; *(const char * *)tb_grow(v_lines) = tb_v1053; }
    { const char * tb_v1054 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1054; }
    { const char * tb_v1055 = "// ---------- уборка памяти: сборщик мусора ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1055; }
    { const char * tb_v1056 = "// Шаги циклов, функции и temp уже отдают память сами (своя временная память).\n"; *(const char * *)tb_grow(v_lines) = tb_v1056; }
    { const char * tb_v1057 = "// А то, что живёт дольше (obj, списки, dict, тексты), раньше жило до конца программы.\n"; *(const char * *)tb_grow(v_lines) = tb_v1057; }
    { const char * tb_v1058 = "// Теперь иногда (когда набралось много новой памяти) программа делает обход:\n"; *(const char * *)tb_grow(v_lines) = tb_v1058; }
    { const char * tb_v1059 = "//   1) смотрит, что видно из переменных: стек, общие (shared) переменные, временная память;\n"; *(const char * *)tb_grow(v_lines) = tb_v1059; }
    { const char * tb_v1060 = "//   2) от них идёт по всему, на что они указывают, и помечает это «нужно»;\n"; *(const char * *)tb_grow(v_lines) = tb_v1060; }
    { const char * tb_v1061 = "//   3) всё не помеченное — мусор, его место отдаётся под новые значения.\n"; *(const char * *)tb_grow(v_lines) = tb_v1061; }
    { const char * tb_v1062 = "// Обход идёт, только когда работает один поток: пока идут background или on all cores, ждём.\n"; *(const char * *)tb_grow(v_lines) = tb_v1062; }
    { const char * tb_v1063 = "// TB_GC=0 — выключить уборку (для проверки), TB_GC_STRESS=N — обход на каждом N-м выделении,\n"; *(const char * *)tb_grow(v_lines) = tb_v1063; }
    { const char * tb_v1064 = "// TB_GC_STATS=1 — печатать каждый обход.\n"; *(const char * *)tb_grow(v_lines) = tb_v1064; }
    { const char * tb_v1065 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1065; }
    { const char * tb_v1066 = "static void *tb_gc_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1066; }
    { const char * tb_v1067 = "    void *p = malloc(n > 0 ? n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1067; }
    { const char * tb_v1068 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1068; }
    { const char * tb_v1069 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1069; }
    { const char * tb_v1070 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1070; }
    { const char * tb_v1071 = "static void tb_gc_free(void *p) { free(p); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1071; }
    { const char * tb_v1072 = "#define tb_gc_alloc_np tb_gc_alloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1072; }
    { const char * tb_v1073 = "static void *tb_gc_realloc(void *p, long long old_n, long long new_n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1073; }
    { const char * tb_v1074 = "    (void)old_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1074; }
    { const char * tb_v1075 = "    p = realloc(p, new_n > 0 ? new_n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1075; }
    { const char * tb_v1076 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1076; }
    { const char * tb_v1077 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1077; }
    { const char * tb_v1078 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1078; }
    { const char * tb_v1079 = "#define tb_gc_root(p, n) ((void)(p), (void)(n))\n"; *(const char * *)tb_grow(v_lines) = tb_v1079; }
    { const char * tb_v1080 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v1080; }
    { const char * tb_v1081 = "#include <setjmp.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v1081; }
    { const char * tb_v1082 = "#define TB_GSH 16\n"; *(const char * *)tb_grow(v_lines) = tb_v1082; }
    { const char * tb_v1083 = "#define TB_GPG (1LL << TB_GSH)\n"; *(const char * *)tb_grow(v_lines) = tb_v1083; }
    { const char * tb_v1084 = "#define TB_GNC 37\n"; *(const char * *)tb_grow(v_lines) = tb_v1084; }
    { const char * tb_v1085 = "#define TB_GBIG 32768\n"; *(const char * *)tb_grow(v_lines) = tb_v1085; }
    { const char * tb_v1086 = "// размеры мелких блоков: страница 64 КБ делится на блоки одного размера (шаг 8 байт у мелких — плотно, как подряд)\n"; *(const char * *)tb_grow(v_lines) = tb_v1086; }
    { const char * tb_v1087 = "static const long long tb_gsz[TB_GNC] = {16, 24, 32, 40, 48, 56, 64, 72, 80, 96, 112, 128, 160, 192, 224, 256,\n"; *(const char * *)tb_grow(v_lines) = tb_v1087; }
    { const char * tb_v1088 = "    320, 384, 448, 512, 640, 768, 1024, 1280, 1536, 2048, 2560, 3072, 4096, 5120, 6144, 8192, 10240, 12288,\n"; *(const char * *)tb_grow(v_lines) = tb_v1088; }
    { const char * tb_v1089 = "    16384, 21840, 32768};\n"; *(const char * *)tb_grow(v_lines) = tb_v1089; }
    { const char * tb_v1090 = "typedef struct tb_gpage {\n"; *(const char * *)tb_grow(v_lines) = tb_v1090; }
    { const char * tb_v1091 = "    char *start;\n"; *(const char * *)tb_grow(v_lines) = tb_v1091; }
    { const char * tb_v1092 = "    long long bsize, nblocks;      // мелкие: размер блока и сколько их\n"; *(const char * *)tb_grow(v_lines) = tb_v1092; }
    { const char * tb_v1093 = "    long long nbytes, cap;         // большой блок: сколько занято и сколько взято\n"; *(const char * *)tb_grow(v_lines) = tb_v1093; }
    { const char * tb_v1094 = "    unsigned long long inv;        // 2^32 / bsize (вверх): номер блока умножением, без деления\n"; *(const char * *)tb_grow(v_lines) = tb_v1094; }
    { const char * tb_v1095 = "    int large, cls, in_avail, np;  // np: внутри нет адресов (числа, тексты) — обход туда не смотрит\n"; *(const char * *)tb_grow(v_lines) = tb_v1095; }
    { const char * tb_v1096 = "    unsigned char *fl;             // по байту на блок: 1 — занят, 2 — нужен (найден при обходе)\n"; *(const char * *)tb_grow(v_lines) = tb_v1096; }
