    { const char * tb_v2287 = "        d->pos = 0; d->npos = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2287; }
    { const char * tb_v2288 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2288; }
