    { const char * tb_v2299 = "// перейти на таблицу с хешем (ключ ушёл далеко от остальных или его удалили)\n"; *(const char * *)tb_grow(v_lines) = tb_v2299; }
    { const char * tb_v2300 = "static void tb_dto_hash(tb_dict *d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2300; }
    { const char * tb_v2301 = "    long long n = 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v2301; }
