    { const char * tb_v2303 = "    tb_dreindex(d, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2303; }
    { const char * tb_v2304 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2304; }
    { const char * tb_v2305 = "// mode 2: таблица pos на ключи base .. base+npos-1\n"; *(const char * *)tb_grow(v_lines) = tb_v2305; }
    { const char * tb_v2306 = "static void tb_dto_pos(tb_dict *d, long long npos) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2306; }
    { const char * tb_v2307 = "    long long *p = tb_dalloc(d, 0, npos * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2307; }
