    { const char * tb_v2319 = "    d->keys = text ? tb_list_new(sizeof(const char *)) : tb_list_new_np(sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v2319; }
    { const char * tb_v2320 = "    d->vals = tb_list_new(vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2320; }
