    { const char * tb_v2322 = "    if (text) tb_dreindex(d, 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v2322; }
    { const char * tb_v2323 = "    else { d->mode = 1; d->nslots = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2323; }
    { const char * tb_v2324 = "    return d;\n"; *(const char * *)tb_grow(v_lines) = tb_v2324; }
    { const char * tb_v2325 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2325; }
    { const char * tb_v2326 = "// .clear(): список снова пустой; свой кусок памяти отдаётся (если он не временный).\n"; *(const char * *)tb_grow(v_lines) = tb_v2326; }
    { const char * tb_v2327 = "// Тексты и obj внутри не удаляются: на них могут смотреть другие переменные.\n"; *(const char * *)tb_grow(v_lines) = tb_v2327; }
    { const char * tb_v2328 = "static void tb_lclear(tb_list *l, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2328; }
    { const char * tb_v2329 = "    if (l->cap < 0) tb_crash(line, \".clear() нельзя, пока по списку идёт each ... by N\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2329; }
    { const char * tb_v2330 = "    int temp = tb_nchunks > 0 && tb_in_temp(l->data);\n"; *(const char * *)tb_grow(v_lines) = tb_v2330; }
    { const char * tb_v2331 = "    if (!temp) tb_gc_free(l->data);\n"; *(const char * *)tb_grow(v_lines) = tb_v2331; }
    { const char * tb_v2332 = "    long long cap = l->size == 0 ? 64 : 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v2332; }
    { const char * tb_v2333 = "    long long bytes = l->size == 0 ? 8 : l->size * 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v2333; }
    { const char * tb_v2334 = "    l->data = tb_in_cur_temp(l->data) ? tb_temp_alloc(bytes) : tb_gc_alloc(bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v2334; }
    { const char * tb_v2335 = "    if (l->data == 0) tb_crash(line, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2335; }
    { const char * tb_v2336 = "    memset(l->data, 0, bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v2336; }
    { const char * tb_v2337 = "    l->len = 0; l->cap = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v2337; }
    { const char * tb_v2338 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2338; }
    { const char * tb_v2339 = "static void tb_dclear(tb_dict *d, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2339; }
    { const char * tb_v2340 = "    tb_lclear(d->keys, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v2340; }
