    { const char * tb_v2439 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2439; }
    { const char * tb_v2440 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v2440; }
