    { const char * tb_v2502 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2502; }
    { const char * tb_v2503 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2503; }
    { const char * tb_v2504 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2504; }
    { const char * tb_v2505 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2505; }
    { const char * tb_v2506 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v2506; }
    { const char * tb_v2507 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v2507; }
    { const char * tb_v2508 = "static pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2508; }
    { const char * tb_v2509 = "static pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v2509; }
    { const char * tb_v2510 = "static int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2510; }
    { const char * tb_v2511 = "static volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2511; }
    { const char * tb_v2512 = "static volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2512; }
    { const char * tb_v2513 = "static void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2513; }
    { const char * tb_v2514 = "static void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2514; }
    { const char * tb_v2515 = "static void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2515; }
    { const char * tb_v2516 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2516; }
    { const char * tb_v2517 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v2517; }
    { const char * tb_v2518 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2518; }
    { const char * tb_v2519 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2519; }
    { const char * tb_v2520 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2520; }
    { const char * tb_v2521 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v2521; }
    { const char * tb_v2522 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2522; }
    { const char * tb_v2523 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v2523; }
    { const char * tb_v2524 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2524; }
    { const char * tb_v2525 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2525; }
    { const char * tb_v2526 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v2526; }
    { const char * tb_v2527 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v2527; }
    { const char * tb_v2528 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v2528; }
    { const char * tb_v2529 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v2529; }
    { const char * tb_v2530 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2530; }
    { const char * tb_v2531 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v2531; }
    { const char * tb_v2532 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2532; }
    { const char * tb_v2533 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2533; }
    { const char * tb_v2534 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2534; }
    { const char * tb_v2535 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2535; }
    { const char * tb_v2536 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v2536; }
    { const char * tb_v2537 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2537; }
    { const char * tb_v2538 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2538; }
    { const char * tb_v2539 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2539; }
    { const char * tb_v2540 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2540; }
    { const char * tb_v2541 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2541; }
    { const char * tb_v2542 = "static void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2542; }
    { const char * tb_v2543 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v2543; }
    { const char * tb_v2544 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v2544; }
    { const char * tb_v2545 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2545; }
    { const char * tb_v2546 = "    if (n == 1) { work(job); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2546; }
    { const char * tb_v2547 = "    // пул уже занят (цикл на ядрах из background или изнутри другого) — по-старому, своими потоками\n"; *(const char * *)tb_grow(v_lines) = tb_v2547; }
    { const char * tb_v2548 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2548; }
    { const char * tb_v2549 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v2549; }
    { const char * tb_v2550 = "        for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2550; }
    { const char * tb_v2551 = "            if (tb_thread_create(&t[i], work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2551; }
    { const char * tb_v2552 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2552; }
    { const char * tb_v2553 = "        for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2553; }
    { const char * tb_v2554 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2554; }
    { const char * tb_v2555 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2555; }
    { const char * tb_v2556 = "    while (tb_pool_n < n - 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2556; }
    { const char * tb_v2557 = "        pthread_t th;\n"; *(const char * *)tb_grow(v_lines) = tb_v2557; }
    { const char * tb_v2558 = "        if (tb_thread_create(&th, tb_pool_loop, (void *)(long long)tb_pool_n) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2558; }
    { const char * tb_v2559 = "        pthread_detach(th);\n"; *(const char * *)tb_grow(v_lines) = tb_v2559; }
    { const char * tb_v2560 = "        tb_pool_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2560; }
    { const char * tb_v2561 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2561; }
    { const char * tb_v2562 = "    pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2562; }
    { const char * tb_v2563 = "    tb_pool_work = work; tb_pool_job = job; tb_pool_want = n - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2563; }
    { const char * tb_v2564 = "    __atomic_store_n(&tb_pool_left, n - 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2564; }
    { const char * tb_v2565 = "    __atomic_add_fetch(&tb_gthreads, n - 1, __ATOMIC_ACQ_REL);\n"; *(const char * *)tb_grow(v_lines) = tb_v2565; }
    { const char * tb_v2566 = "    __atomic_add_fetch(&tb_pool_gen, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2566; }
    { const char * tb_v2567 = "    pthread_cond_broadcast(&tb_pool_go);\n"; *(const char * *)tb_grow(v_lines) = tb_v2567; }
    { const char * tb_v2568 = "    pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2568; }
    { const char * tb_v2569 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v2569; }
    { const char * tb_v2570 = "    if (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2570; }
    { const char * tb_v2571 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v2571; }
    { const char * tb_v2572 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v2572; }
    { const char * tb_v2573 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2573; }
    { const char * tb_v2574 = "        while (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) pthread_cond_wait(&tb_pool_end, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2574; }
    { const char * tb_v2575 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v2575; }
    { const char * tb_v2576 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2576; }
    { const char * tb_v2577 = "    __atomic_store_n(&tb_pool_busy, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v2577; }
    { const char * tb_v2578 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2578; }
    { const char * tb_v2579 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v2579; }
    { const char * tb_v2580 = "static long long tb_par_step(long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2580; }
    { const char * tb_v2581 = "    long long s = total / ((long long)tb_cores() * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v2581; }
